#!/usr/bin/env python3
from pathlib import Path
import json,sys
root=Path(sys.argv[1]);out=Path(sys.argv[2]);checks=[]
def ck(i,ok,d=''):checks.append({'id':i,'passed':bool(ok),'detail':str(d)})
def txt(p):return (root/p).read_text()
paths=['src/games/mk2/research/browserIndexedGraphicsExportBundle.ts','src/games/mk2/research/browserIndexedGraphicsExportBundleValidation.ts','src/components/MK2FoundationPanel.tsx','src/appMetadata.ts','package.json','scripts/run-mk2-indexed-graphics-export-bundle.mjs','scripts/audit-mk2-o70.py']
