ck('o70_verdict','MK2_BROWSER_INDEXED_GRAPHICS_EXPORT_PACKAGE_ESTABLISHED' in s);ck('entries_7678','zipEntryCount: 7678' in s and 'files.length !== 7678' in s);ck('raw_94','rawGraEntryCount: 94' in s and 'resources.length !== 94' in s);ck('streams_3790','indexedPayloadEntryCount: 3790' in s and 'streamCount !== 3790' in s);ck('raw_preservation','rawGraPreservedByteExact: true' in s);ck('palette_false','paletteOwnershipEstablished: false' in s and 'correctColorRgbaEstablished: false' in s);ck('partial_excluded','partialOrAmbiguousResourcesExcluded: true' in s);ck('stable_o69','stableO69Evidence' in s and 'delete copy.timestamp' in s);ck('validator_verdict','MK2_BROWSER_INDEXED_GRAPHICS_EXPORT_BUNDLE_VALIDATED' in v);ck('validator_3790','ALL_3790_INDEX_MASK_PAIRS_RECONSTRUCT' in v);ck('panel_scope','O67–O70' in p);ck('panel_download','Download MK2 Indexed Package' in p);ck('panel_warning','palette ownership and correct-color RGBA remain unestablished' in p);ck('milestone','1E.3O.70' in m);ck('package_script',pkg['scripts'].get('smoke:mk2-indexed-graphics-package')=='node scripts/run-mk2-indexed-graphics-export-bundle.mjs');ck('mk1_unified_retained','smoke:unified-mk1-asset-archive' in pkg['scripts']);
failed=[c for c in checks if not c['passed']];res={'format':'mk2_o70_source_integration_audit_v1','checkCount':len(checks),'passedCount':len(checks)-len(failed),'failedCount':len(failed),'allChecksPassed':not failed,'checks':checks,'decision':{'o70SourceIntegrated':not failed,'mk1WorkflowStillSeparate':True,'verdict':'MK2_O70_SOURCE_UI_INTEGRATION_AUDIT_PASSED' if not failed else 'AUDIT_FAILED'}};out.write_text(json.dumps(res,indent=2));print(json.dumps({k:res[k] for k in ['checkCount','passedCount','failedCount','allChecksPassed']},indent=2));sys.exit(1 if failed else 0)
